head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDSTF30006";
scwin.grd_Grid = null;
scwin.panel_msg = null;
scwin.dts_SCHEDULE = null;
scwin.dts_schelAdmBas = null;
scwin.vUsrId = undefined;
scwin.vUsrTpCd = undefined;
scwin.gLdMktTp = undefined;
scwin.gParamObj = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.tx_script_dts_schelAdmBas();
        scwin.resizeToWin();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30006.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.vUsrId =$c.session.getUserInfo("id"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30006' }); }

try { scwin.vUsrTpCd =js_usr_tp_cd; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30006' }); }

try { scwin.gLdMktTp =$c.session.getUserInfo("market"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30006' }); }

try { scwin.gParamObj =new Array(4); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30006' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.grd_Grid = $c.util.getComponent('grd_Grid');
        scwin.panel_msg = $c.util.getComponent('panel_msg');
        scwin.dts_SCHEDULE = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_SCHEDULE')) : $c.util.getComponent('dts_SCHEDULE');
        scwin.dts_schelAdmBas = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsSchelAdmBas')) : $c.util.getComponent('dtsSchelAdmBas');
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf30006.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description btn_Search 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = async function () {
    try {
        await scwin.tx_script_dts_SCHEDULE();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30006.btn_Search_onclick' }); }
};

/**
 * @method
 * @name dts_SCHEDULE_onloadcompleted
 * @description dts_SCHEDULE onloadcompleted 이벤트
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_SCHEDULE_onloadcompleted = function (rowcount) {
    try {
        // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.fil.PanelMsg
        $c.fil.PanelMsg(scwin.panel_msg, "총 : " + $c.num.formatNumber(rowcount) + " 건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf30006.dts_SCHEDULE_onloadcompleted" });
    }
};

/**
 * @method
 * @name dts_SCHEDULE_onloaderror
 * @description dts_SCHEDULE onloaderror 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.dts_SCHEDULE_onloaderror = function () {
    try {
        $c.win.alert(scwin.dts_SCHEDULE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf30006.dts_SCHEDULE_onloaderror" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description btn_Save 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Save_onclick = async function () {
    try {
        await scwin.sbm_trs_Save();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30006.btn_Save_onclick' }); }
};

/**
 * @method
 * @name trs_Save_onfail
 * @description trs_Save onfail 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_onfail = function () {
    try {
        $c.win.alert(trs_Save);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf30006.trs_Save_onfail" });
