 */
scwin.trs_Save_onsuccess = async function () {
    try {
        await scwin.tx_script_dts_SCHEDULE();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf30006.trs_Save_onsuccess" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description btn_Excel 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function () {
    try {
        scwin.grd_Grid.GridToExcel("공시일정관리항목", '', 8);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30006.btn_Excel_onclick' }); }
};

/**
 * @method
 * @name grd_Grid_ondblclick
 * @description grd_Grid 더블클릭 이벤트
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_ondblclick = function (row, colid) {
    try {
        if (colid === "X_PATH_NM") {
            if (scwin.dts_SCHEDULE.getCellData(row, "DISCLS_SCHDL_ADM_BAS_TP_CD") === '01') {
                scwin.openForm(scwin.dts_SCHEDULE.getCellData(row, "REAL_FORM_CD"), scwin.dts_SCHEDULE.getCellData(row, "REAL_FORM_VER"), slc_cmb_DEP_CD.getValue(), scwin.dts_SCHEDULE.getCellData(row, "X_PATH"), scwin.dts_SCHEDULE.getCellData(row, "SCHDL_ADM_ITM_TP_NM"));
            }
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30006.grd_Grid_ondblclick' }); }
};

/**
 * @method
 * @name txb_SCHDL_ADM_ITM_TP_NM_onclick
 * @description txb_SCHDL_ADM_ITM_TP_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_SCHDL_ADM_ITM_TP_NM_onclick = async function () {
    try {
        if (event.keyCode === 13) {
            await scwin.tx_script_dts_SCHEDULE();
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30006.txb_SCHDL_ADM_ITM_TP_NM_onclick' }); }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_New_onclick = function () {
    try {
        // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
        (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/dsclmgt/ULDSTF39203.gfm", unresolved: "nav:" + "/dsclmgt/ULDSTF39203.gfm" }; })();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30006.btn_New_onclick' }); }
};

/**
 * @method
 * @name btn_RPT_onclick
 * @description btn_RPT 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_RPT_onclick = function () {
    try {
        // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
        (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/dsclmgt/ULDSTF30003.gfm", unresolved: "nav:" + "/dsclmgt/ULDSTF30003.gfm" }; })();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30006.btn_RPT_onclick' }); }
};

/**
 * @method
 * @name txb_FORM_CD_onblur
 * @description txb_FORM_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_FORM_CD_onblur = function () {
    try {
        if (ipt_txb_FORM_CD.value === "") {
            $c.util.getComponent("ipt_txb_FORM_KOR_NM").setValue("");
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30006.txb_FORM_CD_onblur' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_script_dts_schelAdmBas
 * @description script dts schel Adm Bas 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_script_dts_schelAdmBas = async function () {
    $c.util.getComponent("dma_scriptDtsSchelAdmBasReq").set("inputMessageId", "CODEVALUE_INOUT");
    $c.util.getComponent("dma_scriptDtsSchelAdmBasReq").set("outputMessageId", "CODE_OUT");
    $c.util.getComponent("dma_scriptDtsSchelAdmBasReq").set("FOR", "R");
    $c.util.getComponent("dma_scriptDtsSchelAdmBasReq").set("CD_ENG_NM", "DISCLS_SCHDL_ADM_BAS_TP_CD");
    const sbmOptions = {
        id: "tx_script_dts_schelAdmBas",
        method: "post",
        action: "/CodeAction.do",
        ref: "dma_scriptDtsSchelAdmBasReq",
        target: "dtsSchelAdmBas=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_schelAdmBas_onloaderror'] === 'function') ? scwin['dts_schelAdmBas_onloaderror'] : (typeof scwin['dts_schelAdmBas_onfail'] === 'function') ? scwin['dts_schelAdmBas_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_schelAdmBas_onloadcompleted'] === 'function') ? scwin['dts_schelAdmBas_onloadcompleted'] : ((typeof scwin['dts_schelAdmBas_onsuccess'] === 'function') ? scwin['dts_schelAdmBas_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dtsSchelAdmBas'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf30006.tx_script_dts_schelAdmBas" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name tx_script_dts_SCHEDULE
 * @description script dts SCHEDULE 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_script_dts_SCHEDULE = async function () {
    $c.util.getComponent("dma_scriptDts_SCHEDULEReq").set("SCREN_ID", 'ULDSTF30006.gfm');
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "보낼 입력값을 아직 읽지 못합니다(전환 미완) — MKT_ID, FORM_CD, USE_YN, DELETE, ADM_BAS_TP_CD, DEP_CD, SCHDL_ADM_ITM_TP_NM, SUBMIT_SYS_USE_YN, SMS_TRNSM_YN, FORM_KOR_NM, SCREN_PROCES_TP_CD"
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — MKT_ID, FORM_CD, USE_YN, DELETE, ADM_BAS_TP_CD, DEP_CD, SCHDL_ADM_ITM_TP_NM, SUBMIT_SYS_USE_YN, SMS_TRNSM_YN, FORM_KOR_NM, SCREN_PROCES_TP_CD", unresolved: "query_param:MKT_ID,FORM_CD,USE_YN,DELETE,ADM_BAS_TP_CD,DEP_CD,SCHDL_ADM_ITM_TP_NM,SUBMIT_SYS_USE_YN,SMS_TRNSM_YN,FORM_KOR_NM,SCREN_PROCES_TP_CD" };
    const sbmOptions = {
        id: "tx_script_dts_SCHEDULE",
        method: "post",
        action: "/DisclosureSchedule.do",
        ref: "dma_scriptDts_SCHEDULEReq",
        target: "dts_SCHEDULE=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_SCHEDULE_onloaderror'] === 'function') ? scwin['dts_SCHEDULE_onloaderror'] : (typeof scwin['dts_SCHEDULE_onfail'] === 'function') ? scwin['dts_SCHEDULE_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_SCHEDULE_onloadcompleted'] === 'function') ? scwin['dts_SCHEDULE_onloadcompleted'] : ((typeof scwin['dts_SCHEDULE_onsuccess'] === 'function') ? scwin['dts_SCHEDULE_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_SCHEDULE'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf30006.tx_script_dts_SCHEDULE" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name sbm_trs_Save
 * @description trs Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sbm_trs_Save = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — sbm_trs_Save"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — sbm_trs_Save", unresolved: "action:self_submit:sbm_trs_Save" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name disclsClose
 * @description discls Close 처리
 * @returns {void}
 * @hidden N
 */
scwin.disclsClose = function () {
    dts_SCHEDULE.setBroadcast(false);
    for (let i = 1; i <= scwin.dts_SCHEDULE.CountRow; i++) {
        scwin.dts_SCHEDULE.setCellData(i, "REMK", scwin.dts_SCHEDULE.getCellData(i, "REMK") + "(서식폐지)");
    }
    dts_SCHEDULE.setBroadcast(true, true);
};

/**
 * @method
 * @name openForm
 * @description open Form 처리
 * @param {*} form_cd form_cd
 * @param {*} form_ver form_ver
 * @param {*} dep_cd dep_cd
 * @param {*} x_path x_path
 * @param {*} schdl_adm_itm_tp_nm schdl_adm_itm_tp_nm
 * @returns {void}
 * @hidden N
 */
scwin.openForm = function (form_cd, form_ver, dep_cd, x_path, schdl_adm_itm_tp_nm) {
    const form_x_path = scwin.StringToHex4(schdl_adm_itm_tp_nm) + ":" + x_path;
    let url;
    if (js_svrGubun.indexOf("test") > -1) {
        url = g_test_manager_url + "/filing/findForm.do?method=scheduleFormView";
    } else {
        if (js_svrGubun === 'dev') {
            url = g_dev_manager_url + "/filing/findForm.do?method=scheduleFormView";
        } else {
            url = g_real_manager_url + "/filing/findForm.do?method=scheduleFormView";
        }
    }
    url += "&formCd=" + form_cd;
    url += "&formVer=" + form_ver;
    url += "&form_x_path=" + form_x_path;
    const winTitle = url;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { id: "formPop", type: "pageFramePopup", title: winTitle, width: "800px", height: "700px" }, {});
};

/**
 * @method
 * @name StringToHex4
 * @description String To Hex4 처리
 * @param {*} OriginalString OriginalString
 * @returns {void}
 * @hidden N
 */
scwin.StringToHex4 = function (OriginalString) {
    let ReturnString = "";
    for (let i = 0; i < OriginalString.length; i++) {
        const tmp = "0000" + (parseInt(OriginalString.charCodeAt(i)).toString(16));
        const tmp2 = tmp.substring(tmp.length - 4);
        ReturnString += tmp2;
    }
    return ReturnString.toUpperCase();
};

/**
 * @method
 * @name getFormXPath
 * @description get Form XPath 처리
 * @param {*} form_cd form_cd
 * @param {*} x_path x_path
 * @returns {void}
 * @hidden N
 */
scwin.getFormXPath = function (form_cd, x_path) {
    let str = "";
    for (let i = 0; i < scwin.dts_SCHEDULE.CountRow; i++) {
        if (form_cd === scwin.dts_SCHEDULE.getCellData(i, "FORM_CD")) {
            if (i === 0) {
                str += scwin.dts_SCHEDULE.getCellData(i, "SCHDL_ADM_ITM_TP_NM");
                str += ":" + scwin.dts_SCHEDULE.getCellData(i, "X_PATH");
            } else {
                str += "," + scwin.dts_SCHEDULE.getCellData(i, "SCHDL_ADM_ITM_TP_NM");
                str += ":" + scwin.dts_SCHEDULE.getCellData(i, "X_PATH");
            }
        }
    }
    return str;
};

/**
 * @method
 * @name resizeToWin
 * @description resize To Win 처리
 * @returns {void}
 * @hidden N
 */
scwin.resizeToWin = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.Height, $c.frame.Width
    $c.frame.Width = 1300;
    $c.frame.Height = 800;
};

/**
 * @method
 * @name grd_Grid_cancolumnposchange
 * @description grd Grid cancolumnposchange 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_cancolumnposchange = function (row, colid) {
    try {
        return true;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30006.grd_Grid_cancolumnposchange' }); }
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
